// RESTful 资源命名 + HTTP 方法语义 + 状态码映射（纯函数，无 I/O）
const SAFE = new Set(['GET', 'HEAD', 'OPTIONS', 'TRACE']);
const IDEMPOTENT = new Set(['GET', 'HEAD', 'PUT', 'DELETE', 'OPTIONS', 'TRACE']);

// 资源命名判据：小写复数名词、连字符分词、不含动词、不含扩展名
function isGoodResourceName(name) {
  if (!/^[a-z][a-z0-9-]*s$/.test(name)) return false;                   // 小写复数名词
  if (/(get|create|update|delete|list|fetch|query)/.test(name)) return false; // 不含动词
  if (name.includes('.')) return false;                                  // 不含文件扩展名
  if (/[A-Z_]/.test(name)) return false;                                 // 不用驼峰/下划线
  return true;
}

// 场景 → 状态码（语义判定，不是「能返回 200 就算对」）
function statusFor(scenario) {
  const M = {
    collection_listed: 200, item_read: 200, item_replaced: 200, item_patched: 200,
    item_created: 201, item_deleted: 204,
    malformed_json: 400, unauthenticated: 401, unknown_route: 404, id_missing: 404,
    method_not_allowed: 405, duplicate_unique_key: 409, unsupported_media_type: 415,
    schema_invalid: 422, rate_limited: 429, dependency_down: 500,
  };
  if (!(scenario in M)) throw new Error('unknown scenario: ' + scenario);
  return M[scenario];
}

function classOf(status) { return status + ' (' + Math.floor(status / 100) + 'xx)'; }

console.log('resource_name_judgement:');
for (const n of ['articles', 'users', 'articleList', 'getUsers', 'user_profile', 'article']) {
  console.log('  ' + n.padEnd(14) + 'valid=' + isGoodResourceName(n));
}

console.log('method_semantics:');
for (const m of ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD']) {
  console.log('  ' + m.padEnd(7) + 'safe=' + String(SAFE.has(m)).padEnd(6)
    + 'idempotent=' + IDEMPOTENT.has(m));
}

